modern_c4_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    boats = image_patch.find("boat")
    docks = image_patch.find("dock")

    if not boats or not docks:
        return image_patch

    boat_dock_pairs = []
    for boat in boats:
        for dock in docks:
            if is_between_3d(boat, dock, dock):
                boat_dock_pairs.append((boat, dock))

    if not boat_dock_pairs:
        return boats[0]

    boat_distances = [(pair[0], distance(pair[0], pair[1])) for pair in boat_dock_pairs]
    boat_distances.sort(key=lambda x: x[1])

    return boat_distances[-1][0]

