def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    marbles = image_patch.find("marble")
    tables = image_patch.find("tabletop")
    bottles = image_patch.find("bottle of beer")

    if not marbles or not tables or not bottles:
        return image_patch

    marble_table_pairs = [(m, t) for m in marbles for t in tables if m.overlaps_with(t.left, t.lower, t.right, t.upper)]
    valid_pairs = []

    for marble, table in marble_table_pairs:
        bottle_distances = [distance(marble, b) for b in bottles if b.overlaps_with(table.left, table.lower, table.right, table.upper)]
        if bottle_distances:
            min_distance = min(bottle_distances)
            if all(abs(d - min_distance) < 0.1 for d in bottle_distances):  # Assuming a small tolerance for proximity
                valid_pairs.append((marble, table))

    if not valid_pairs:
        return image_patch

    return max(valid_pairs, key=lambda x: x[0].horizontal_center + x[1].vertical_center)

