    basket_patches = image_patch.find("basket")
    plant_patches = image_patch.find("flowering plants")
    box_patches = image_patch.find("cardboard boxes")

    if not basket_patches or not plant_patches or not box_patches:
        return image_patch

    basket_center_y = sum(p.vertical_center for p in basket_patches) / len(basket_patches)
    plant_centers_y = [(p.vertical_center, p) for p in plant_patches]
    box_centers_y = [(p.vertical_center, p) for p in box_patches]

    plant_on_top_of_box = []
    for _, plant in sorted(plant_centers_y, reverse=True):
        for _, box in sorted(box_centers_y, reverse=True):
            if plant.overlaps_with(box.left, box.lower, box.right, box.upper):
                plant_on_top_of_box.append((abs(plant.vertical_center - box.vertical_center), plant))
                break

    if not plant_on_top_of_box:
        return image_patch

    basket_full_of_plants = []
    for _, plant in sorted(plant_on_top_of_box, reverse=True):
        for _, basket in sorted(basket_centers_y, reverse=True):
            if plant.overlaps_with(basket.left, basket.lower, basket.right, basket.upper):
                basket_full_of_plants.append((abs(plant.vertical_center - basket.vertical_center), plant))
                break

    if not basket_full_of_plants:
        return image_patch

    return basket_full_of_pl

